def squash(s: str) -> str:
    """Compress s by encoding runs of length >= 3 and escaping digits and backslashes."""
    out: list[str] = []
    n = len(s)
    i = 0
    while i < n:
        ch = s[i]
        j = i + 1
        while j < n and s[j] == ch:
            j += 1
        count = j - i
        escaped = f"\\{ch}" if ("0" <= ch <= "9" or ch == "\\") else ch
        if count >= 3:
            out.append(f"{count}{escaped}")
        else:
            out.append(escaped * count)
        i = j
    return "".join(out)
